    }

    let comments = splitComments(comment)
    if (comments.length >= 2) sleepToast("✅ 发送评论\n\n正在拆分长评论，即将逐条发送")
    comments.forEach(comment => {
        sleep(0.5 * Math.random())
        let matched = comment.match(RegExp(/(；|;\s*)\d{8,}/))
        if (matched) {
